import logging

from ..timeout import Timeout
from ute_common_util.ignore import ignore_exceptions_other_than, ignore_exceptions
from .executor import CmdExecutor
from .parser import NmapParser
from .exception import NoHostFound, ScannerException, ScannerExecutionTimeout
from .manager import ExecutionManager


log = logging.getLogger("ARP")


class ArpScanner(object):
    """ArpScanner is able to scan network/hosts via ARP protocol.

    .. code-block:: python

        scanner = ArpScanner()
        answered_hosts = scanner.scan_network('10.0.2.0/24', timeout=10)
        answered_hosts = scanner.scan_hosts('10.0.2.1', '10.0.2.2', timeout=3)
        answered_host = scanner.wait_for_any_host('10.0.2.1', '10.0.2.2', timeout=60)

    It is possible to use different than local executor. Executor object has to have *execute_command* method.

    .. code-block:: python

        scanner = ArpScanner(executor=ssh_client)
        scanner = scanner.scan_network('10.0.2.0/24', timeout=1)

    ArpScanner is designed to run properly on POSIX systems (like linux). Please set posix to False to run ArpScanner on Windows system.

    .. code-block:: python

        scanner = ArpScanner(posix=False)
        scanner = scanner.scan_network('10.0.2.0/24', timeout=10)
    """
    def __init__(self, executor=None, posix=True):
        """
        :param executor:        Instance with execute_command method. In case of lack of executor CmdExecutor will be used.
        :param boolean posix:   Set library to work with Linux (True) or Windows (False).
        """
        self._cmd_builder = _ArpScannerCmdBuilder(posix)
        self._nmap_parser = NmapParser()
        self._executor = executor
        self._manager = ExecutionManager()

    def scan_network(self, network, **kwargs):
        """Method to scan network.

        :param string network: Network IP Address/Mask e.g. 1.1.1.0/24

        Scanning *timeout* can be specified via kwargs parameter.
        Default timeout is 10 seconds.

        :return: Discovered hosts.
        :rtype: list
        """
        timeout = kwargs.get('timeout', 10)
        exec_cmd = self._cmd_builder.build_scan_network_cmd(network)
        out = self._execute_command(exec_cmd, timeout)
        return self._nmap_parser.find_hosts(out)

    def scan_hosts(self, *hosts, **kwargs):
        """Method to scan specified hosts.

        :param hosts: List of hosts to scan.

        Scanning *timeout* can be specified via kwargs parameter.
        Default timeout is 3 seconds.

        :return: Discovered hosts.
        :rtype: list
        """
        timeout = kwargs.get('timeout', 3)
        exec_cmd = self._cmd_builder.build_scan_hosts_cmd(hosts)
        out = self._execute_command(exec_cmd, timeout)
        return self._nmap_parser.find_hosts(out)

    def wait_for_any_host(self, *hosts, **kwargs):
        """Method to wait until one of specified hosts answer or timeout occurs.

        :param hosts: List of hosts to scan.

        Scanning *timeout* can be specified via kwargs parameter.
        Default timeout is 60 seconds.

        :return: First discovered host.
        :rtype: string
        """
        timeout = kwargs.get('timeout', 60)
        cmd = self._cmd_builder.build_scan_hosts_cmd(hosts)
        answered = self._wait_for_answered_hosts(cmd, timeout)
        if answered:
            return answered[0]
        raise NoHostFound("Scanner is not able to find any host.")

    def _wait_for_answered_hosts(self, cmd, timeout):
        timeout = Timeout(timeout)
        while timeout.is_not_reached():
            out = self._execute_command(cmd, timeout.time_left())
            answered = self._nmap_parser.find_hosts(out)
            if answered:
                return answered

    @ignore_exceptions_other_than([ScannerException], "", log.debug)
    @ignore_exceptions([ScannerExecutionTimeout], "", log.debug)
    def _execute_command(self, cmd, timeout):
        executor = CmdExecutor(timeout) if self._executor is None else self._executor
        return self._manager.run(timeout, executor.execute_command, cmd)


class _ArpScannerCmdBuilder(object):

    BASE_CMD = "nmap -n -sP -PR {} -oG -"

    def __init__(self, posix):
        """
        :param boolean posix:   Set library to work with Linux (True) or Windows (False).
        """
        self._posix = posix

    def build_scan_network_cmd(self, network):
        """Method to build execution command for scanning network.

        :param string network: Network IP Address/Mask e.g. 1.1.1.0/24

        :return: Created shell command.
        :rtype: string
        """
        cmd = _ArpScannerCmdBuilder.BASE_CMD.format(network)
        if self._posix:
            return 'sudo {}'.format(cmd)
        return cmd

    def build_scan_hosts_cmd(self, hosts):
        """Method to build execution command for scanning hosts.

        :param list hosts: List of hosts to scan.

        :return: Created shell command.
        :rtype: string
        """
        cmd = _ArpScannerCmdBuilder.BASE_CMD.format(' '.join(hosts))
        if self._posix:
            return 'sudo {}'.format(cmd)
        return cmd
